{"explanation":"Scaling by \(k\) multiplies every length in the triangle—such as its base and height—by \(k\). Since \(A=\tfrac12 bh\), both factors contribute: \(A'=\tfrac12(kb)(kh)=k^2A\). Move the slider to compare the original triangle with its scaled copy.","manimCode":"const title = new Text({ text: 'Why area scales as k²', color: WHITE, fontSize: 34 });
title.moveTo([0, 3.25, 0]);

const formula = new MathTex({ latex: 'A=\\frac12bh\\quad\\longrightarrow\\quad A\u0027=\\frac12(kb)(kh)=k^2A' });
await formula.waitForRender();
formula.moveTo([0, 2.45, 0]);

const hint = new Text({ text: 'Use the slider: every horizontal and vertical length is multiplied by k.', color: GRAY, fontSize: 19 });
hint.moveTo([0, 1.85, 0]);

const localVerts = [[-1.1, -0.7, 0], [1.1, -0.7, 0], [-0.5, 1.1, 0]];
const leftCenter = [-3.0, -0.45, 0];
const rightCenter = [2.7, -0.45, 0];

function translatedVerts(center, factor) {
  return localVerts.map(p => [center[0] + factor * p[0], center[1] + factor * p[1], 0]);
}

const original = new Polygon({ vertices: translatedVerts(leftCenter, 1), color: BLUE });
original.setFill(BLUE_E, 0.48).setStrokeWidth(3);
const scaled = new Polygon({ vertices: translatedVerts(rightCenter, 1), color: YELLOW });
scaled.setFill(YELLOW, 0.38).setStrokeWidth(3);

const originalLabel = new Text({ text: 'original: base b, height h', color: BLUE_B, fontSize: 20 });
originalLabel.moveTo([-3.0, -2.35, 0]);
const scaledLabel = new Text({ text: 'scaled copy: kb, kh', color: YELLOW, fontSize: 20 });
scaledLabel.moveTo([2.7, -2.35, 0]);

const arrow = new Arrow({ start: [-1.25, -0.35, 0], end: [0.95, -0.35, 0], color: WHITE });
const arrowLabel = new MathTex({ latex: '\\times k' });
await arrowLabel.waitForRender();
arrowLabel.moveTo([-0.15, 0.1, 0]);

scene.add(title, formula, hint, original, scaled, originalLabel, scaledLabel, arrow, arrowLabel);

let factor = 1;
const controls = new Controls(scene, { position: 'bottom-right', theme: 'dark', width: 255 });
controls.addSlider({
  label: 'Scale factor k', min: 0.4, max: 1.7, value: 1, step: 0.1,
  onChange: (value) => {
    factor = value;
    scaled.setVertices(translatedVerts(rightCenter, factor));
  }
});
controls.addButton({ label: 'Reset k = 1', onClick: () => {
  factor = 1;
  scaled.setVertices(translatedVerts(rightCenter, factor));
}});

makeHoverable(original, scene, { hoverOpacity: 0.7 });
makeHoverable(scaled, scene, { hoverOpacity: 0.65 });

await scene.wait(999999);"}

